from pathlib import Path

import pandas as pd
from openpyxl.styles import Font
from openpyxl.utils import get_column_letter


def export_dataframe_to_excel(
    df: pd.DataFrame,
    export_file: str | Path,
    *,
    sheet_name: str = "Daten",
    max_column_width: int = 50,
    index: bool = False,
) -> Path:
    """Exportiert einen DataFrame nach Excel, formatiert die Kopfzeile und passt Spaltenbreiten an."""

    export_path = Path(export_file)
    export_path.parent.mkdir(parents=True, exist_ok=True)

    with pd.ExcelWriter(export_path, engine="openpyxl") as writer:
        df.to_excel(
            writer,
            index=index,
            sheet_name=sheet_name,
        )

        worksheet = writer.sheets[sheet_name]

        for cell in worksheet[1]:
            cell.font = Font(bold=True)

        worksheet.auto_filter.ref = worksheet.dimensions

        for column_number, cells in enumerate(worksheet.iter_cols(), start=1):
            max_content_length = max(
                (
                    len(str(cell.value))
                    if cell.value is not None
                    else 0
                )
                for cell in cells
            )

            column_letter = get_column_letter(column_number)
            worksheet.column_dimensions[column_letter].width = min(
                max_content_length + 2,
                max_column_width,
            )

    return export_path